 for($field=0;$field-lt7;$field++){$row=$bases[$field]+$values[$field];if(($row*7+6)-ge$rpg1PersonalityWeights.Count){$boxes['--personality'].SelectedIndex=7;return};for($p=0;$p-lt7;$p++){$scores[$p]+=$rpg1PersonalityWeights[$row*7+$p];if($scores[$p]-gt$best){$best=$scores[$p];$winner=$p}}}
