function Set-Rpg1Bits([byte[]]$Bytes,[int]$Offset,[int]$Bit,[int]$Width,[int]$Value){for($i=0;$i-lt$Width;$i++){$absolute=$Bit+$i;$at=$Offset+[Math]::Floor($absolute/8);$mask=1-shl($absolute%8);if(($Value-band(1-shl$i))-ne0){$Bytes[$at]=[byte]($Bytes[$at]-bor$mask)}else{$Bytes[$at]=[byte]($Bytes[$at]-band(255-bxor$mask))}}}
function Set-Rpg1Pair([byte[]]$Bytes,[int[]]$Low,[int]$LowValue,[int[]]$High,[int]$HighValue){Set-Rpg1Bits $Bytes $Low[0] $Low[1] $Low[2] $LowValue;if($High){Set-Rpg1Bits $Bytes $High[0] $High[1] $High[2] $HighValue}}
